def campaign_to_plot_input(campaign):
    """
    Converte il risultato di run_multipath_campaign nel formato
    atteso da plot_all: {"nlos_paths": [...]}

    Uso:
        results_per_terrain = {
            "Flat":     campaign_to_plot_input(campaign_flat),
            "Basin":    campaign_to_plot_input(campaign_basin),
            "Slope":    campaign_to_plot_input(campaign_slope),
            "Mountain": campaign_to_plot_input(campaign_mountain),
        }
        plot_all(results_per_terrain, frequenza=2.4e9)
    """
    return {"nlos_paths": campaign["all_paths"]}

def print_full_ray_history_2(risultati):
    """
    Stampa un report unificato, dettagliato e diagnostico per tutti i percorsi 
    multipath calcolati dal simulatore di ray-tracing.
    """
    print(f"\n{'='*95}")
    print(f"{'REPORT DETTAGLIATO E DIAGNOSTICA PERCORSI MULTIPATH':^95}")
    print(f"{'='*95}\n")
 
    for i, path in enumerate(risultati['nlos_paths']):
 
        is_los          = path['bounces'] == 0
        is_diffracted   = path.get('has_diffracted', False)
        has_reflections = any(
            b.get('tipo', 'reflection') == 'reflection'
            for b in path.get('dettaglio_rimbalzi', [])
        )
 
        if is_los:
            tag           = "[L]"
            tipo_percorso = "LoS Analitico (Diretto)"
        elif is_diffracted and has_reflections:
            tag           = "[M]"
            tipo_percorso = f"NLoS Mixed — Reflection+Diffraction ({path['bounces']} bounce(s))"
        elif is_diffracted:
            tag           = "[K]"
            tipo_percorso = f"NLoS Diffracted — Keller ({path['bounces']} bounce(s))"
        else:
            tag           = "[P]"
            tipo_percorso = f"NLoS Pure Reflection ({path['bounces']} bounce(s))"
 
        # Arrival (RX) and departure (TX) angles, global + local frames.
        aoa_az_g = path.get('aoa_azimuth_global_deg',   path.get('aoa_azimuth_deg', 0.0))
        aoa_el_g = path.get('aoa_elevation_global_deg', path.get('aoa_elevation_deg', 0.0))
        aoa_az_l = path.get('aoa_azimuth_local_deg',   float('nan'))
        aoa_el_l = path.get('aoa_elevation_local_deg', float('nan'))
        aod_az_g = path.get('aod_azimuth_global_deg',   float('nan'))
        aod_el_g = path.get('aod_elevation_global_deg', float('nan'))
        aod_az_l = path.get('aod_azimuth_local_deg',   float('nan'))
        aod_el_l = path.get('aod_elevation_local_deg', float('nan'))
        r_val = path.get("r_influence_used")
        n_micro = len(path.get("membro_raggruppamento", [])) or 1
 
        # ── Estrazione diretta dal dizionario (NO RICALCOLO) ───────────
        fsl_db       = path.get('fsl_db', 0.0)
        refl_loss_db = path.get('reflection_loss_db', 0.0)
        diff_loss_db = path.get('diffraction_loss_db', 0.0)
        gain_tx      = path.get('gain_tx_db', 0.0)
        gain_rx      = path.get('gain_rx_db', 0.0)
        # LoS stores the polarization mismatch under 'IL_db'; NLoS under 'pol_loss'
        pol_loss     = path.get('pol_loss', path.get('IL_db', 0.0))
        family_id    = path.get('ray_id', 'N/A')
 
        # Per-path budget (one representative micro-ray), end to end incl. gains
        path_budget = (fsl_db + refl_loss_db + pol_loss + diff_loss_db
                       - gain_tx - gain_rx)
 
        # Honest coherent-vs-incoherent interference of the SAME bundle:
        #   coh  = -20log10|Σ campo_i|      (fields added with phase)
        #   inc  = -20log10 sqrt(Σ|campo_i|^2)   (powers added, phase ignored)
        # interference = coh - inc  ->  0 dB for a single ray, <0 constructive, >0 destructive
        # campo_complesso is now the AVERAGE over the bundle; the coherent SUM
        # is n_micro * campo. Compare coherent-sum vs incoherent-sum magnitude.
        coh_mag = n_micro * abs(path['campo_complesso'])
        P_inc   = path.get('potenza_incoerente', abs(path['campo_complesso']) ** 2)
        inc_mag = np.sqrt(P_inc)
        coh_loss = -20.0 * np.log10(coh_mag) if coh_mag > 1e-15 else float('inf')
        inc_loss = -20.0 * np.log10(inc_mag) if inc_mag > 1e-15 else float('inf')
        interference_db = coh_loss - inc_loss
 
        # ── Stampe principali ─────────────────────────────────────────
        print(f"--- PERCORSO #{i} {tag} | {tipo_percorso} | Family ID #{family_id} ---")
        if not is_los:
            print(f"  Composizione SBR : {n_micro} micro-raggio/i -> 1 componente coerente")
        print(f"  Distanza totale  : {path['distanza_totale']:.2f} m")
        r_str = f"{r_val:.6f} m" if r_val is not None else "N/A (LoS deterministico)"
        print(f"  R Influence Used : {r_str}")
        print(f"  Ritardo assoluto : {path['ritardo_assoluto_ns']:.2f} ns")
        print(f"  Fase segnale     : {path['sfasamento_totale_deg']:.1f}°")
        print(f"  |Campo|          : {abs(path['campo_complesso']):.6e}")
 
        # ── Budget di perdita (un singolo micro-raggio rappresentativo) ─
        print(f"  Budget di perdita (per micro-raggio):")
        print(f"     FSL            : {fsl_db:8.2f} dB")
        if not is_los:
            print(f"     Riflessione    : {refl_loss_db:8.2f} dB")
        print(f"     Polarizzazione : {pol_loss:8.2f} dB")
        if abs(diff_loss_db) > 1e-9:
            print(f"     Diffrazione    : {diff_loss_db:8.2f} dB")
        print(f"     Guadagni Ant.  : {-(gain_tx + gain_rx):+8.2f} dB   "
              f"(TX {gain_tx:+.2f} | RX {gain_rx:+.2f} dBi)")
        print(f"     {'-'*28}")
        print(f"     Perdita path   : {path_budget:8.2f} dB")
 
        # ── Interferenza del bundle (onesta: coerente vs incoerente) ───
        if is_los or n_micro <= 1:
            print(f"  Interferenza SBR :    +0.00 dB   (raggio singolo: nessuna interferenza)")
        else:
            tipo_int = ("costruttiva" if interference_db < -0.05
                        else "distruttiva (fading)" if interference_db > 0.05
                        else "trascurabile")
            print(f"  Interferenza SBR : {interference_db:+8.2f} dB   "
                  f"({n_micro} raggi combinati coerentemente -> {tipo_int})")
                
        print(f"  Angoli Partenza (TX) [global = travel dir | local = vs boresight]:")
        print(f"     Globale : Azimuth {aod_az_g:>7.1f}°, Elevation {aod_el_g:>7.1f}°")
        print(f"     Locale  : Azimuth {aod_az_l:>7.1f}°, Elevation {aod_el_l:>7.1f}°")
        print(f"  Angoli Arrivo   (RX) [global = travel dir | local = came-from vs boresight]:")
        print(f"     Globale : Azimuth {aoa_az_g:>7.1f}°, Elevation {aoa_el_g:>7.1f}°")
        print(f"     Locale  : Azimuth {aoa_az_l:>7.1f}°, Elevation {aoa_el_l:>7.1f}°")
 
        # ── Cronologia Rimbalzi ───────────────────────────────────────
        if not is_los:
            print("  Cronologia Rimbalzi:")
            for j, bounce in enumerate(path['dettaglio_rimbalzi']):
                p             = bounce['punto_impatto']
                face          = bounce['face_id']
                tipo          = bounce.get('tipo', 'reflection')
                ang_incidenza = bounce['angolo_incidenza_deg']
                ang_grazing   = 90.0 - ang_incidenza
 
                if tipo == 'diffraction':
                    ed_dir = bounce.get('edge_dir', [0, 0, 0])
                    d_mag  = bounce.get('D_coef_mag', float('nan'))
                    d_ph   = bounce.get('D_coef_phase_deg', float('nan'))
                    d_db   = -20.0 * np.log10(d_mag) if d_mag > 1e-12 else float('inf')
                    print(f"    -> Evento {j+1}: [DIFFRAZIONE KELLER]")
                    print(f"       - Punto Impatto (Edge)     : [{p[0]:.2f}, {p[1]:.2f}, {p[2]:.2f}]")
                    print(f"       - Edge Dir                 : [{ed_dir[0]:.3f}, {ed_dir[1]:.3f}, {ed_dir[2]:.3f}]")
                    print(f"       - β₀ (incidenza su edge)   : {ang_incidenza:.1f}°")
                    print(f"       - |D|                      : {d_mag:.6f}  ({d_db:.2f} dB)")
                    print(f"       - Phase(D)                 : {d_ph:.1f}°")
                else:
                    print(f"    -> Rimbalzo {j+1}: [RIFLESSIONE]")
                    print(f"       - Face ID                  : {face}")
                    print(f"       - Punto Impatto            : [{p[0]:.2f}, {p[1]:.2f}, {p[2]:.2f}]")
                    print(f"       - Angolo Incid. (Normal)   : {ang_incidenza:.1f}°")
                    print(f"       - Angolo Grazing (Surface) : {ang_grazing:.1f}°")
                    rte = bounce.get('R_TE')
                    rtm = bounce.get('R_TM')
                    if rte is not None and rtm is not None:
                        print(f"       - Coeff. Fresnel R_TE      : {rte.real:+.3f}{rte.imag:+.3f}j  (|R|={abs(rte):.3f})")
                        print(f"       - Coeff. Fresnel R_TM      : {rtm.real:+.3f}{rtm.imag:+.3f}j  (|R|={abs(rtm):.3f})")
                    rl = bounce.get('refl_loss_db')
                    if rl is not None:
                        print(f"       - Reflection Loss          : {rl:.2f} dB")
                    pb = bounce.get('pol_before')
                    pa = bounce.get('pol_after')
                    if pb is not None and pa is not None:
                        print(f"       - Polarizzazione           : {pb} (AR {bounce.get('ar_before_db', float('nan')):.1f} dB) "
                              f"-> {pa} (AR {bounce.get('ar_after_db', float('nan')):.1f} dB)")
        else:
            print("  Stato            : Percorso Diretto LoS (Nessun rimbalzo)")
 
        print("-" * 75 + "\n")
 
    print(f"{'='*95}\n")


def _los_reference_angles(pos_tx, pos_rx):
    """AoA (az, el) at RX of the direct TX->RX direction, in degrees.
    Matches the engine's LoS convention: arrival direction = pos_tx - pos_rx."""
    d = np.asarray(pos_tx, float) - np.asarray(pos_rx, float)
    n = np.linalg.norm(d)
    if n < 1e-12:
        return 0.0, 0.0
    ref_az = np.degrees(np.arctan2(d[1], d[0]))
    ref_el = np.degrees(np.arcsin(np.clip(d[2] / n, -1.0, 1.0)))
    return ref_az, ref_el


def _wrap180(a):
    """Wrap an angle (deg) to (-180, 180]."""
    return (a + 180.0) % 360.0 - 180.0


def _extract_arrays(campaign_results):
    """Pull flat arrays from raw campaign results."""
    delay_ns, power_lin = [], []
    aoa_az_rel, aoa_el_rel = [], []
    rms_ds_list = []

    for entry in campaign_results:
        paths = entry["result"]["nlos_paths"]

        # Per-link LoS reference direction (relative AoA is measured from this)
        ref_az, ref_el = _los_reference_angles(entry["pos_tx"], entry["pos_rx"])

        pair_delays, pair_powers = [], []

        for p in paths:
            campo = complex(p["campo_complesso"])
            e2 = abs(campo) ** 2                       # = path power |campo|^2

            delay_ns.append(p["ritardo_assoluto_ns"])
            power_lin.append(e2)

            # FIX 2: relative AoA (Δα wrapped to ±180°, Δβ as difference)
            aoa_az_rel.append(_wrap180(p["aoa_azimuth_deg"] - ref_az))
            aoa_el_rel.append(p["aoa_elevation_deg"] - ref_el)

            # collect NLoS only for RMS-DS (as in the original draft)
            if p["bounces"] > 0:
                pair_delays.append(p["ritardo_assoluto_ns"])
                pair_powers.append(e2)

        # RMS-DS per link (paper eq. 11-12): power-weighted second moment of delay
        if len(pair_delays) > 1:
            d = np.array(pair_delays)
            w = np.array(pair_powers)                  # FIX 1: weight = power (NOT power**2)
            w = w / w.sum()
            tau_mean = np.dot(w, d)
            rms_ds = float(np.sqrt(max(np.dot(w, d ** 2) - tau_mean ** 2, 0.0)))
            rms_ds_list.append(rms_ds)

    return (
        np.array(delay_ns),
        np.array(power_lin),
        np.array(aoa_az_rel),
        np.array(aoa_el_rel),
        np.array(rms_ds_list),
    )

def plot_pattern_2D(path, coel=45):
    pat = pattern_from_grap(path)
    az = np.linspace(0, 360, 5000)

    # ---- azimuth cut at chosen coelevation + its peak ----
    gains = pat(np.full_like(az, coel), az)
    cut_max = gains.max()
    az_cut_peak = az[gains == cut_max]            # azimuth(s) of the cut's peak

    fig = go.Figure(go.Scatterpolar(r=gains, theta=az, mode="lines"))
    fig.add_trace(go.Scatterpolar(
        r=[cut_max]*len(az_cut_peak), theta=az_cut_peak, mode="markers",
        name=f"cut max ({cut_max:.2f} dBW)",
        marker=dict(color="red", size=10, symbol="circle")))
    fig.update_layout(
        title=f"EIRP azimuth cut at coel = {coel:.0f}°",
        polar=dict(radialaxis=dict(title="EIRP [dBW]", range=[-30, 30]),
                   angularaxis=dict(rotation=90, direction="clockwise")))
    fig.show()

    # ---- global max from the grid's OWN axes ----
    i_th, i_ph = np.unravel_index(np.argmax(pat.grid), pat.grid.shape)
    coel_max, az_max, gmax = pat.theta[i_th], pat.phi[i_ph], pat.grid.max()
    print(f"Global max {gmax:.2f} dBW @ Co-Elev: {coel_max:.1f}° | Az: {az_max:.1f}°")

    # ---- 3D balloon + arrow to the global max ----
    G  = pat.grid
    TH = np.deg2rad(pat.theta)[:, None]; PH = np.deg2rad(pat.phi)[None, :]
    r  = G - G.min()
    X = r*np.sin(TH)*np.cos(PH); Y = r*np.sin(TH)*np.sin(PH); Z = r*np.cos(TH)
    fig = go.Figure(go.Surface(x=X, y=Y, z=Z, surfacecolor=G, colorscale="Turbo",
                               colorbar=dict(title="EIRP [dBW]")))

    th, ph = np.deg2rad(coel_max), np.deg2rad(az_max)
    L = 1.15 * r.max()
    x_max = L*np.sin(th)*np.cos(ph); y_max = L*np.sin(th)*np.sin(ph); z_max = L*np.cos(th)
    plot_vector3d(fig, [0, 0, 0], [x_max, y_max, z_max], 'red', width = 15)

    fig.update_layout(title="GRAP E1 EIRP - 3D balloon", scene=dict(aspectmode="data"))
    fig.show()

    